mapper.select:
SELECT a.board_id ,a.category as category_cd ,b.dtl_nm as category ,a.title ,a.content ,a.author ,COALESCE(a.use_yn, 'N') as use_yn ,TO_CHAR(a.reg_date, 'YYYY-MM-DD') as reg_date ,TO_CHAR(a.upt_date, 'YYYY-MM-DD') as upt_date FROM tb_board a INNER JOIN tb_common_code_dtl b ON a.category = b.dtl_cd AND b.mst_cd = 'boardType' WHERE 1=1
AND a.category = #{category}
AND title like CONCAT('%', #{title}, '%')
